def gen(rng):
    def fmt(rows):
        return f"{len(rows)} {len(rows[0])}\n" + "\n".join(rows)
    tests = [
        fmt(["a"]), fmt(["aa", "aa"]), fmt(["ab", "ba"]), fmt(["aaaaa"]),
        fmt(["a", "a", "a", "a"]), fmt(["aaa", "aba", "aaa"]), fmt(["aaa", "aca", "aaa"][:3]),
        fmt(["abb", "bab", "bbb"]), fmt(["aab", "aba", "bbb"]),
    ]
    def rand_grid(r, c, k):
        return ["".join(rng.choice("abcdefghijklmnopqrstuvwxyz"[:k]) for _ in range(c)) for _ in range(r)]
    for _ in range(40):
        r = rng.randint(1, 5)
        c = rng.randint(1, 5)
        k = rng.choice([2, 3, 3, 4, 5, 6])
        tests.append(fmt(rand_grid(r, c, k)))
    # big tests
    R, C = 400, 400
    # comb: a-tree plus vertical b paths, no cycle
    comb = []
    for i in range(R):
        row = []
        for j in range(C):
            row.append('a' if (i == 0 or j % 2 == 0) else 'b')
        comb.append(row)
    tests.append(fmt(["".join(r) for r in comb]))
    hidden = [row[:] for row in comb]
    for (i, j) in ((R - 2, C - 2), (R - 2, C - 1), (R - 1, C - 2), (R - 1, C - 1)):
        hidden[i][j] = 'z'
    tests.append(fmt(["".join(r) for r in hidden]))
    tests.append(fmt(rand_grid(R, C, 26)))
    tests.append(fmt(rand_grid(R, C, 2)))
    # large snake: one long a-path separated by b walls, no cycle
    snake = []
    for i in range(R):
        if i % 2 == 0:
            snake.append('a' * C)
        else:
            snake.append(('b' * (C - 1) + 'a') if (i // 2) % 2 == 0 else ('a' + 'b' * (C - 1)))
    tests.append(fmt(snake))
    return tests

